const fs = require('fs');
const path = require('path');

const schemaPath = path.join(__dirname, 'schema', 'core.prisma');
const schemaContent = fs.readFileSync(schemaPath, 'utf8');

// The routing rules
const routing = {
    auth: ['Account', 'Session', 'VerificationToken', 'User', 'TenantUserMapping', 'UserPreference'],
    company: ['Company', 'CompanyCoreValue', 'CompanyPublicReview', 'CompanyFollower', 'CompanyService', 'CompanyProduct', 'CompanyMedia', 'CompanyInvestor', 'Job', 'Application', 'JobApplication', 'JobCandidateProfile', 'JobOpportunity', 'Onboarding'],
    community: ['ForumPost', 'ForumReply', 'SavedPost', 'Hashtag', 'PostReport', 'PollOption', 'PollVote'],
    events: ['Event', 'EventRegistration', 'CalendarEvent', 'MeetingLog'],
    learning: ['LearningPath', 'Track', 'Course', 'CourseModule', 'Lesson', 'Assessment', 'QuizQuestion', 'AssessmentSubmission', 'Enrollment', 'LessonProgress', 'Certificate', 'UserCertificate', 'Competency', 'UserBadge'],
    communications: ['Chat', 'Message', 'EmailLog', 'Notification'],
    platform: ['PlatformSettings', 'Plan', 'Subscription', 'Coupon', 'PaymentHistory', 'SuperAdmin', 'DeletionLog', 'FeatureFlag', 'Announcement', 'ReleaseNote', 'SupportTicket', 'AuditLog', 'AiRequestLog', 'AutomationLog', 'AiChatSession', 'AiChatMessage'],
    user_profile: ['UserExperience', 'UserEducation', 'Skill', 'UserSkill', 'UserResume', 'UserProject'],
    content: ['Note', 'Category', 'Document', 'DocumentPage', 'CalendarContentPiece', 'CalendarTemplate', 'ContentCalendar', 'Settings', 'ServiceRequest', 'ActivityLog']
};

const routeMap = {};
for (const [file, models] of Object.entries(routing)) {
    for (const model of models) {
        routeMap[model] = file;
    }
}

// Simple parser to chunk by top-level blocks
const lines = schemaContent.split('\n');
const chunks = [];
let currentChunk = [];
let currentName = null;
let currentType = null;
let braceDepth = 0;

for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    
    if (braceDepth === 0) {
        const match = line.match(/^(model|enum|generator|datasource)\s+(\w+)/);
        if (match) {
            currentType = match[1];
            currentName = match[2];
        }
    }
    
    currentChunk.push(line);
    
    braceDepth += (line.match(/\{/g) || []).length;
    braceDepth -= (line.match(/\}/g) || []).length;
    
    if (braceDepth === 0 && currentChunk.join('\n').trim().length > 0 && currentType) {
        chunks.push({
            type: currentType,
            name: currentName,
            content: currentChunk.join('\n')
        });
        currentChunk = [];
        currentType = null;
        currentName = null;
    } else if (braceDepth === 0 && currentChunk.join('\n').trim().length === 0) {
        // Just empty lines between chunks
        currentChunk = [];
    }
}

// Group chunks by file
const files = {
    core: [] // generator, datasource, and unmapped models
};

for (const chunk of chunks) {
    if (chunk.type === 'generator' || chunk.type === 'datasource') {
        files.core.push(chunk.content);
        continue;
    }
    
    const file = routeMap[chunk.name] || 'core';
    if (!files[file]) files[file] = [];
    files[file].push(chunk.content);
}

// Write to files
for (const [file, contents] of Object.entries(files)) {
    const outPath = path.join(__dirname, 'schema', `${file}.prisma`);
    fs.writeFileSync(outPath, contents.join('\n\n'));
    console.log(`Wrote ${contents.length} blocks to ${file}.prisma`);
}
